const groups={"Identität & Einstieg":['brand','meta','year','heroPrefix','heroEmphasis','heroSuffix','heroSubline','heroSetup','quote'],Fundament:['foundationLead','principle1Title','principle1Text','principle2Title','principle2Text','principle3Title','principle3Text'],Rollen:['strategyName','strategyRole','strategyText','creativeName','creativeRole','creativeText'],Akquise:['acquisitionLead','acquisitionLead1','acquisition1Title','acquisition1Text','acquisition2Title','acquisition2Text'],"Realitätscheck & Abschluss":['realityPrefix','realityEmphasis','risk1Title','risk1Text','risk2Title','risk2Text','risk3Title','risk3Text','closingPrefix','closingEmphasis','closingText','status','footerNote']};
const labels={brand:'Markenname',meta:'Kopfzeile',year:'Jahr',heroPrefix:'Titel, erster Teil',heroEmphasis:'Titel, kursiver Teil',heroSuffix:'Titel, letzter Teil',heroSubline:'Unterzeile',heroSetup:'Setup-Zeile',quote:'Leitsatz',foundationLead:'Einleitung',principle1Title:'Prinzip I — Titel',principle1Text:'Prinzip I — Text',principle2Title:'Prinzip II — Titel',principle2Text:'Prinzip II — Text',principle3Title:'Prinzip III — Titel',principle3Text:'Prinzip III — Text',strategyName:'Strategy — Name',strategyRole:'Strategy — Rolle',strategyText:'Strategy — Beschreibung',creativeName:'Creative — Name',creativeRole:'Creative — Rolle',creativeText:'Creative — Beschreibung',acquisitionLead:'Akquise — Einleitung',acquisition1Title:'Akquise A — Titel',acquisition1Text:'Akquise A — Text',acquisition2Title:'Akquise B — Titel',acquisition2Text:'Akquise B — Text',realityPrefix:'Realität — erster Teil',realityEmphasis:'Realität — kursiver Teil',risk1Title:'Hürde 01 — Titel',risk1Text:'Hürde 01 — Gegenmaßnahme',risk2Title:'Hürde 02 — Titel',risk2Text:'Hürde 02 — Gegenmaßnahme',risk3Title:'Hürde 03 — Titel',risk3Text:'Hürde 03 — Gegenmaßnahme',closingPrefix:'Abschluss — erster Teil',closingEmphasis:'Abschluss — kursiver Teil',closingText:'Abschluss — Text',status:'Status',footerNote:'Footer-Notiz'};
let content={},csrf='';const login=document.querySelector('#login'),editor=document.querySelector('#editor'),toast=document.querySelector('#toast');const notify=t=>{toast.textContent=t;toast.style.display='block';setTimeout(()=>toast.style.display='none',4000)};
document.querySelector('#login-form').addEventListener('submit',async e=>{e.preventDefault();const message=document.querySelector('#login-message');try{const r=await fetch('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password:document.querySelector('#password').value})});const data=await r.json().catch(()=>({}));if(!r.ok){message.textContent=data.error||'Editor-Server nicht erreichbar.';return}csrf=data.csrf;openEditor()}catch(error){message.textContent='Editor-Server nicht erreichbar. Bitte npm run dev starten.'}});
async function openEditor(){const r=await fetch('/api/editor-content');if(!r.ok)return;content=await r.json();login.hidden=true;editor.hidden=false;const form=document.querySelector('#editor-form');form.innerHTML='';Object.entries(groups).forEach(([name,keys])=>{const section=document.createElement('section');section.innerHTML=`<h2>${name}</h2>`;keys.forEach(key=>{const value=content[key]||'',multi=value.length>90;const row=document.createElement('div');row.className='field';const label=document.createElement('label');label.htmlFor=key;label.textContent=labels[key];const input=document.createElement(multi?'textarea':'input');input.id=key;input.dataset.key=key;input.value=value;row.append(label,input);section.append(row)});form.append(section)});await loadDocuments()}
async function loadDocuments(){const section=document.createElement('section');section.id='documents';section.innerHTML='<h2>Dokumente</h2><div class="field"><label for="document-select">Markdown-Datei</label><select id="document-select"></select></div><div class="field"><label for="document-content">Inhalt</label><textarea id="document-content" rows="24" spellcheck="false"></textarea></div><button class="publish" id="save-document" type="button">Dokument speichern</button>';document.querySelector('#editor-form').after(section);const list=await fetch('/api/docs');if(!list.ok)return;const files=await list.json();const select=section.querySelector('#document-select');files.forEach(file=>{const option=document.createElement('option');option.value=file;option.textContent=file;select.append(option)});const load=async()=>{const response=await fetch(`/api/docs/${encodeURIComponent(select.value)}`);if(response.ok)section.querySelector('#document-content').value=(await response.json()).content};select.addEventListener('change',load);if(files.length)await load()}
document.addEventListener('click',async event=>{if(event.target.id==='save-document'){const select=document.querySelector('#document-select'),textarea=document.querySelector('#document-content');if(!select||!textarea)return;const button=event.target;button.disabled=true;const r=await fetch(`/api/docs/${encodeURIComponent(select.value)}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csrf,content:textarea.value})});button.disabled=false;if(!r.ok)return notify((await r.json()).error);notify(`${select.value} gespeichert.`)}if(event.target.id==='publish'){const next={};document.querySelectorAll('[data-key]').forEach(e=>next[e.dataset.key]=e.value);const r=await fetch('/api/content',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csrf,content:next})});if(!r.ok)return notify((await r.json()).error);content=next;notify('Veröffentlicht. Die Seite ist aktuell.')}if(event.target.id==='logout'){await fetch('/api/logout',{method:'POST'});location.reload()}});
